package com.trombokendu.chronos.persistence;import java.sql.*;import java.util.*;import com.trombokendu.chronos.domain.*;public abstract class JdbcRepository<T,ID> implements Repository<T,ID>{protected final ConnectionPool pool;protected JdbcRepository(ConnectionPool p){pool=p;}protected abstract String selectOneSql();protected abstract String selectAllSql();protected abstract String insertSql();protected abstract T map(ResultSet r)throws SQLException;protected abstract void bind(PreparedStatement s,T v)throws SQLException;protected abstract void bindId(PreparedStatement s,ID id)throws SQLException;public Optional<T> find(ID id){try(Connection c=pool.get();PreparedStatement s=c.prepareStatement(selectOneSql())){bindId(s,id);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}catch(SQLException e){throw new PersistenceException("find failed",e);}}public List<T> findAll(){try(Connection c=pool.get();PreparedStatement s=c.prepareStatement(selectAllSql());ResultSet r=s.executeQuery()){List<T> out=new ArrayList<>();while(r.next())out.add(map(r));return List.copyOf(out);}catch(SQLException e){throw new PersistenceException("findAll failed",e);}}public void save(T v){try(Connection c=pool.get();PreparedStatement s=c.prepareStatement(insertSql())){bind(s,v);s.executeUpdate();}catch(SQLException e){throw new PersistenceException("save failed",e);}}}
